-- Lista completa de campanhas (SCC) com prazo, última visita e oportunidade perdida.

alter table public.campaign_machines
  add column if not exists dealer_code text,
  add column if not exists scc_status text,
  add column if not exists machine_campaign_status text,
  add column if not exists repair_deadline date,
  add column if not exists submission_deadline date,
  add column if not exists last_visit date,
  add column if not exists opportunity_lost boolean not null default false;

on conflict (code) do nothing;

on conflict (campaign_code, model, serial_number) do update set
  branch = excluded.branch,
  recommendation = excluded.recommendation,
  dealer_code = excluded.dealer_code,
  scc_status = excluded.scc_status,
  machine_campaign_status = excluded.machine_campaign_status,
  repair_deadline = excluded.repair_deadline,
  submission_deadline = excluded.submission_deadline,
  last_visit = excluded.last_visit,
  opportunity_lost = excluded.opportunity_lost,
  updated_at = now();

select private.refresh_inspection_150h();
